def sieve(n):
    marks = [True] * (n + 1)
    p = 2
    while p * p <= n:
        if marks[p]:
            m = p * p
            while m <= n:
                marks[m] = False
                m = m + p
        p = p + 1
    primes = []
    for k in range(2, n + 1):
        if marks[k]:
            primes.append(k)
    return primes


m = int(input())
for i in range(m):
    a = int(input())
    b = int(input())
    found = []
    for p in sieve(b):
        if p >= a:
            found.append(p)
    print(found)
    print(f"{len(found)} primes from {a} to {b}")

